PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE occupancies (   id INTEGER PRIMARY KEY AUTOINCREMENT,   room_id INTEGER NOT NULL,   nama_penyewa TEXT NOT NULL,   no_hp TEXT,   asal_kampus TEXT,   tipe_sewa TEXT NOT NULL CHECK(tipe_sewa IN ('harian','mingguan','bulanan','semesteran','tahunan')),   tanggal_mulai DATE NOT NULL,   tanggal_selesai DATE NOT NULL,   harga_total INTEGER NOT NULL,   status_bayar TEXT NOT NULL DEFAULT 'belum' CHECK(status_bayar IN ('lunas','dp','belum')),   link_kontrak TEXT,   catatan TEXT,   created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,   updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, no_ktp TEXT, alamat_penyewa TEXT, no_ktp_ortu TEXT, nama_ortu TEXT, no_hp_ortu TEXT, alamat_ortu TEXT, hubungan_keluarga TEXT, file_ktp_penyewa TEXT, file_ktp_ortu TEXT, file_ktm TEXT, file_perjanjian TEXT,   FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE CASCADE );
CREATE TABLE admin_users (   id INTEGER PRIMARY KEY AUTOINCREMENT,   username TEXT NOT NULL UNIQUE,   nama_lengkap TEXT,   password_hash TEXT NOT NULL,   role TEXT NOT NULL DEFAULT 'admin' CHECK(role IN ('owner','admin')),   aktif INTEGER NOT NULL DEFAULT 1,   created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE sessions (   token TEXT PRIMARY KEY,   user_id INTEGER NOT NULL,   expires_at TIMESTAMP NOT NULL,   created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,   FOREIGN KEY (user_id) REFERENCES admin_users(id) ON DELETE CASCADE );
CREATE TABLE counter (   id INTEGER PRIMARY KEY CHECK(id=1),   count INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE login_attempts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      ip TEXT NOT NULL,
      attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE visitor_logs (   id INTEGER PRIMARY KEY AUTOINCREMENT,   ip TEXT,   country TEXT,   country_name TEXT,   city TEXT,   region TEXT,   timezone TEXT,   latitude TEXT,   longitude TEXT,   isp TEXT,   user_agent TEXT,   browser TEXT,   browser_version TEXT,   os TEXT,   device_type TEXT,   referer TEXT,   path TEXT,   visited_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP , viewed INTEGER DEFAULT 0, viewed_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS "rooms" (   id INTEGER PRIMARY KEY AUTOINCREMENT,   nama_kamar TEXT NOT NULL UNIQUE,   tipe TEXT NOT NULL CHECK(tipe IN ('AC','NON-AC')),   harga_bulanan INTEGER NOT NULL,   urutan INTEGER DEFAULT 0,   created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_occ_room ON occupancies(room_id);
CREATE INDEX idx_occ_tanggal ON occupancies(tanggal_selesai);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);
CREATE INDEX idx_visitor_date ON visitor_logs(visited_at);
CREATE INDEX idx_visitor_ip ON visitor_logs(ip);
CREATE INDEX idx_visitor_browser ON visitor_logs(browser);
